import {
    isProgramError,
    type Address,
    type HasAddress,
    type SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM,
    type SolanaError,
} from '@solana/kit';
import { INSTRUCTIONS_PROGRAM_ADDRESS } from '../programs';

export const INSTRUCTIONS_ERROR__TEMPLATED = 0x1; // 1

export type InstructionsError = typeof INSTRUCTIONS_ERROR__TEMPLATED;

let instructionsErrorMessages: Record<InstructionsError, string> | undefined;
if (process.env['NODE_ENV'] !== 'production') {
    instructionsErrorMessages = { [INSTRUCTIONS_ERROR__TEMPLATED]: `Expected \${amount} \\ got \`value\`.` };
}

export function getInstructionsErrorMessage(code: InstructionsError): string {
    if (process.env['NODE_ENV'] !== 'production') {
        return (instructionsErrorMessages as Record<InstructionsError, string>)[code];
    }

    return 'Error message not available in production bundles.';
}

export function isInstructionsError<TProgramErrorCode extends InstructionsError>(
    error: unknown,
    transactionMessage: { instructions: Record<number, { programAddress: Address }> },
    code?: TProgramErrorCode,
    config: { programAddress?: Address | HasAddress } = {},
): error is SolanaError<typeof SOLANA_ERROR__INSTRUCTION_ERROR__CUSTOM> &
    Readonly<{ context: Readonly<{ code: TProgramErrorCode }> }> {
    const programAddressInput = config.programAddress ?? INSTRUCTIONS_PROGRAM_ADDRESS;
    const programAddress = typeof programAddressInput === 'string' ? programAddressInput : programAddressInput.address;
    return isProgramError<TProgramErrorCode>(error, transactionMessage, programAddress, code);
}
